import{_ as t,o as i,c as a,a2 as e}from"./chunks/framework.BVc2lkLk.js";const c=JSON.parse('{"title":"AI 能力：LLM 接口插件","description":"想让插件用上大模型，装 LLM 接口插件；Agent 插件是一个现成的消费方，可以拿来用，也可以自己写。","frontmatter":{"description":"想让插件用上大模型，装 LLM 接口插件；Agent 插件是一个现成的消费方，可以拿来用，也可以自己写。"},"headers":[],"relativePath":"ai.md","filePath":"ai.md","lastUpdated":1793349588000}'),n={name:"ai.md"};function l(r,s,d,h,o,p){return i(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="ai-能力-llm-接口插件" tabindex="-1">AI 能力：LLM 接口插件 <a class="header-anchor" href="#ai-能力-llm-接口插件" aria-label="Permalink to &quot;AI 能力：LLM 接口插件&quot;">​</a></h1><p>机器人本身不含任何模型接入。谁需要 AI 能力（对话、总结、改写、生成），就装 <strong>LLM 接口</strong>插件，通过它提供的 <code>llm</code> 服务调用模型。</p><ul><li><strong>LLM 接口</strong>（<code>llm</code>）：供应商与模型别名管理 + 统一的 <code>chat</code> / <code>stream</code> 接口。它是<strong>能力提供方</strong>，所有要用模型的插件都依赖它。</li><li><strong>Agent</strong>（<code>agent</code>）：一个<strong>消费方示范</strong>——拿 <code>llm</code> 服务做多轮对话、工具调用、会话记忆。它证明这套接口够用，但不是我方提供的唯一形态；有人想做一个更好的 Agent、甚至换个方向（翻译、审稿、群管助手），直接照着 <code>llm</code> 的接口写自己的插件即可，不需要跟 Agent 插件绑在一起。</li></ul><p>两者都<strong>不是</strong>内置插件（<a href="./builtin-plugins">内置插件</a>只有 <code>sid</code> 和 <code>t2i</code>），在<a href="./market">插件市场</a>单独安装、单独升级。</p><h2 id="装-llm-接口" tabindex="-1">装 LLM 接口 <a class="header-anchor" href="#装-llm-接口" aria-label="Permalink to &quot;装 LLM 接口&quot;">​</a></h2><p><code>llm</code> 没有硬依赖，装完配好就能被别的插件用。仓库：<a href="https://github.com/clown145/qflarebot-plugin-llm" target="_blank" rel="noreferrer">qflarebot-plugin-llm</a>。</p><p>配好只需要一次：</p><ol><li>侧栏「插件页面 → LLM 接口」→「模型服务」左侧点「添加」，选一个服务商模板（OpenAI 兼容或 Anthropic），填 API Key 保存。</li><li>点「刷新上游」读接口的模型列表，用「+」逐个添加或「全部添加」；也可以「添加模型」手填上游模型名，<strong>别名</strong>供调用方使用。</li><li>在「设置」里选默认模型别名和超时，点「保存设置」。</li><li>「概览」里执行一次测试，确认地址、Key、模型都通。</li></ol><p>几点要知道的：</p><ul><li><strong>配置只在插件页面改，不在面板的「插件配置」卡片里</strong>。这个插件没有声明 <code>configSchema</code>，那张卡片对它是摆设，写进去的值不会被读取，而且字段不脱敏——<strong>不要往那里写 API Key</strong>。</li><li>API Key 存在插件自己的 KV 里，接口只回「已设置」的布尔值，页面不回显；导出的 JSON 不含 Key。</li><li>接口地址只接受 <code>https</code>，并拒绝回环与内网地址。不要在「额外请求头」里写 <code>Authorization</code> / <code>x-api-key</code>，这两个头由插件按 Key 生成。</li><li>模型元数据可以从 <a href="https://models.dev" target="_blank" rel="noreferrer">models.dev</a> 按需填充，运行时不会去请求它。</li><li>群里发 <code>/llm</code> 查看当前模型与可用列表，<code>/llm use &lt;序号或别名&gt;</code> 切换<strong>全局默认</strong>（不是按会话）。</li></ul><h2 id="在自己的插件里用模型" tabindex="-1">在自己的插件里用模型 <a class="header-anchor" href="#在自己的插件里用模型" aria-label="Permalink to &quot;在自己的插件里用模型&quot;">​</a></h2><p>声明依赖，然后从 <code>ctx.service(&#39;llm&#39;)</code> 取：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> definePlugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  depends: { llm: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 必需；想「没装也能跑」就写 &#39;optional&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  commands: {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    summarize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">argText</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> llm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LLMService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;llm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        model: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;chat&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 模型别名；省略则用 LLM 页面里设的默认模型</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        messages: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          { role: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;system&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, content: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;把用户给的内容压缩成一句话。&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          { role: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, content: argText },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      })</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result.text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">??</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;模型没有返回内容&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>接口是 <code>listModels</code> / <code>resolve</code> / <code>chat</code> / <code>stream</code> / <code>ping</code>，完整类型见插件仓库的 <code>src/contract.ts</code>。<code>LLMService</code> 这类类型不在 <code>@qqbot/sdk</code> 里，复制一份到自己的插件（Agent 插件就是本地复制了一份最小定义），<strong>不要</strong> import 对方的源码——那是构建期依赖，插件之间只该通过服务名对接。几个规则：</p><ul><li><strong>调用方按别名要模型，不写供应商或上游模型名</strong>。用户换供应商、换模型时，插件不用改。</li><li>服务名就是接口约定。接口要改会换服务名（<code>llm2</code>），不会原地改形状。</li><li><code>depends</code> 写 <code>&#39;*&#39;</code> 是硬依赖：没装 LLM 时安装会被直接拒绝，不会装上一个跑不起来的插件。想要「有就用、没有就降级」就写 <code>&#39;optional&#39;</code>，取不到时 <code>ctx.service()</code> 会抛错，自己 <code>try/catch</code>。</li><li><strong>免费版的额度是全机器人共享的</strong>：一次事件所有插件合计 30 秒、50 个子请求，CPU 共 10 ms。模型请求本身就占一个子请求、几百毫秒到几十秒，所以<strong>别在每条消息都会走到的路径上调模型</strong>，也别为了一条消息连调好几次。</li></ul><h2 id="agent-一个现成的消费方" tabindex="-1">Agent：一个现成的消费方 <a class="header-anchor" href="#agent-一个现成的消费方" aria-label="Permalink to &quot;Agent：一个现成的消费方&quot;">​</a></h2><p><a href="https://github.com/clown145/qflarebot-plugin-agent" target="_blank" rel="noreferrer">qflarebot-plugin-agent</a> 是 <code>llm</code> 服务的一个<strong>示范消费方</strong>：多轮对话、工具调用、会话记忆、定时提醒。它说明这套接口能撑到什么程度，但不是我方提供的唯一形态，也不限制别人怎么做。</p><p>想直接用：先装 <code>llm</code> 再装 <code>agent</code>（市场里两个一起勾会自动按依赖顺序写清单），然后在侧栏「插件页面 → Agent」选一个模型别名、点「测试连通性」即可。群里 @机器人 或打 <code>/</code> 前缀都能触发，<code>/help</code> 看全部命令。它声明了 DO 类，面板预检会给一句提醒，<strong>不需要</strong>改 <code>apps/seed/wrangler.jsonc</code>。</p><p>想做更好的、或者换个方向（翻译、审稿、群管助手），直接照 <code>llm</code> 的接口写自己的插件就行，不必和 Agent 绑定。</p><h3 id="自己写的话-先看额度" tabindex="-1">自己写的话，先看额度 <a class="header-anchor" href="#自己写的话-先看额度" aria-label="Permalink to &quot;自己写的话，先看额度&quot;">​</a></h3><p>欢迎做更好的实现，但请先算一笔账——下面几项是<strong>全机器人共享</strong>的（免费版），一个 AI 插件把额度吃光，整台机器人一起停摆：</p><table tabindex="0"><thead><tr><th>资源</th><th>免费版额度</th><th>对 AI 插件意味着什么</th></tr></thead><tbody><tr><td>D1 写入</td><td>10 万行/天</td><td>不要每条消息都写一行，审计/统计这类要么关掉、要么攒批</td></tr><tr><td>KV</td><td>写/删/列各 1,000 次/天</td><td>只存配置这类很少变的东西；计数与会话状态放 D1 或 DO</td></tr><tr><td>Durable Object</td><td>13,000 GB-s/天</td><td>按「128 MB × 活跃时长」计费，<strong>一个被持续访问的 DO 一天约 11,000 GB-s</strong>，几乎吃掉全额度</td></tr><tr><td>子请求</td><td>50 次/事件</td><td>一次模型调用就是一个子请求；工具调用会再连锁几个，要自己数</td></tr><tr><td>CPU</td><td>10 ms/事件</td><td>大 JSON 解析、长循环、base64 编码都别放热路径</td></tr><tr><td>请求数</td><td>10 万次/天</td><td>声明 <code>* * * * *</code> 的 cron 跟着框架那个每分钟触发器跑，一天先占 1,440 次</td></tr></tbody></table><p>Agent 为压住这些做过的取舍（会话状态与会话锁放 DO、限流计数放 DO、审计默认关、工具步数默认 8）可以对着看。完整限额表见<a href="./plugin-guide#_9-平台限额-免费版的硬预算">插件开发指南 · 平台限额</a>。</p><h2 id="更多文档" tabindex="-1">更多文档 <a class="header-anchor" href="#更多文档" aria-label="Permalink to &quot;更多文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="https://github.com/clown145/qflarebot-plugin-llm" target="_blank" rel="noreferrer">LLM 接口 README</a></td><td>供应商模板、请求头、模型元数据、<code>llm</code> 服务接口与 <code>contract.ts</code></td></tr><tr><td><a href="https://github.com/clown145/qflarebot-plugin-agent/blob/main/docs/quickstart.md" target="_blank" rel="noreferrer">Agent 快速开始</a></td><td>装、配、跑起来</td></tr><tr><td><a href="https://github.com/clown145/qflarebot-plugin-agent/blob/main/docs/configuration.md" target="_blank" rel="noreferrer">Agent 配置说明</a></td><td>每个配置项的含义与取舍</td></tr><tr><td><a href="https://github.com/clown145/qflarebot-plugin-agent/blob/main/docs/tools.md" target="_blank" rel="noreferrer">Agent 工具与权限</a></td><td>工具清单、权限怎么算、安全防线</td></tr><tr><td><a href="https://github.com/clown145/qflarebot-plugin-agent/blob/main/docs/plugin-api.md" target="_blank" rel="noreferrer">Agent 插件 API</a></td><td>用 <code>ctx.service(&#39;agent&#39;)</code> 往 Agent 里注册提示词片段与工具</td></tr></tbody></table><p>想让自己的插件也对外提供服务、给别的插件用，看<a href="./plugin-guide#要读别的插件的数据">插件开发指南 · 要读别的插件的数据</a>。</p>`,26)])])}const g=t(n,[["render",l]]);export{c as __pageData,g as default};
